CREATE TABLE "student" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "first_name" VARCHAR2(35)   NOT NULL,
    "last_name" VARCHAR2(70)   NOT NULL,
    "email" VARCHAR2(70) NOT NULL,
    "dob" DATE   NOT NULL,
    "gender" NUMBER(1)   NOT NULL,
    "phone_number" VARCHAR2(70) NOT NULL,
    "nationality" VARCHAR2(70),
    "special_needs" VARCHAR2(70),
    "comments" VARCHAR2(70),
    "major" VARCHAR2(70),
    "minor" VARCHAR2(70),
    "isWaiting" NUMBER(1)  DEFAULT 0 NOT NULL,
    "status" NUMBER   NOT NULL,
    "course" NUMBER   NOT NULL,
    "category" NUMBER   NOT NULL,
    "address" NUMBER   NOT NULL,
    "advisor" NUMBER   NOT NULL,
    CONSTRAINT "pk_student" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "advisor" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "first_name" VARCHAR2(35)   NOT NULL,
    "last_name" VARCHAR2(70)   NOT NULL,
    "email" VARCHAR2(70) NOT NULL,
    "room_number" NUMBER   NOT NULL,
    "phone_number" VARCHAR2(70)   NOT NULL,
    "position" NUMBER   NOT NULL,
    "department" VARCHAR2(70),
    "address" NUMBER   NOT NULL,
    CONSTRAINT "pk_advisor" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "staff" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "first_name" VARCHAR2(70)   NOT NULL,
    "last_name" VARCHAR2(70)   NOT NULL,
    "email" VARCHAR2(70)   NOT NULL,
    "dob" DATE,
    "phone_number" VARCHAR2(70)   NOT NULL,
    "gender" NUMBER(1)   NOT NULL,
    "position" NUMBER   NOT NULL,
    "address" NUMBER   NOT NULL,
    CONSTRAINT "pk_staff" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "instructor" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "first_name" VARCHAR2(35)   NOT NULL,
    "last_name" VARCHAR2(70)   NOT NULL,
    "email" VARCHAR2(70)   NOT NULL,
    "department" VARCHAR2(70),
    "room_number" VARCHAR2(70)   NOT NULL,
    CONSTRAINT "pk_instructor" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "next_of_kin" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "first_name" VARCHAR2(35)   NOT NULL,
    "last_name" VARCHAR2(70)   NOT NULL,
    "phone_number" VARCHAR2(70)   NOT NULL,
    "relationship" NUMBER   NOT NULL,
    "student" NUMBER   NOT NULL,
    "address" NUMBER   NOT NULL,
    CONSTRAINT "pk_next_of_kin" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "relationship_type" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "name" VARCHAR2(70)   NOT NULL,
    "description" VARCHAR2(70),
    CONSTRAINT "pk_relationship_type" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "staff_position" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "name" VARCHAR2(70)   NOT NULL,
    "description" VARCHAR2(70),
    CONSTRAINT "pk_staff_position" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "student_category" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "name" VARCHAR2(70)   NOT NULL,
    "description" VARCHAR2(70),
    CONSTRAINT "pk_student_category" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "status" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "name" VARCHAR2(70)   NOT NULL,
    "description" VARCHAR2(70),
    CONSTRAINT "pk_status" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "hall_of_residence" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "name" VARCHAR2(70)  DEFAULT 'hall of residence',
    "phone_number" VARCHAR2(70)   NOT NULL,
    "manager" NUMBER   NOT NULL,
    "address" NUMBER   NOT NULL,
    CONSTRAINT "pk_hall_of_residence" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "room_inspection" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "inspector" NUMBER   NOT NULL,
    "date_of_inspection" DATE   NOT NULL,
    "satisfactory_condition" NUMBER(1)  DEFAULT 1,
    "comments" VARCHAR2(70),
    "place_number" NUMBER   NOT NULL,
    CONSTRAINT "pk_room_inspection" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "room" (
    "place_number" NUMBER GENERATED by default on null as IDENTITY,
    "room_number" NUMBER   NOT NULL,
    "monthly_rent_rate" DECIMAL(6,2)  DEFAULT 0.0,
    "hall_of_residence" NUMBER   NOT NULL,
    CONSTRAINT "pk_room" PRIMARY KEY (
        "place_number"
     )
);

CREATE TABLE "lease" (
    "lease_number" NUMBER GENERATED by default on null as IDENTITY,
    "start" DATE   NOT NULL,
    "end" DATE   NOT NULL,
    "move_in" DATE   NOT NULL,
    "move_out" DATE   NOT NULL,
    "student_id" NUMBER   NOT NULL,
    "place_number" NUMBER   NOT NULL,
    "is_expired" NUMBER(1)  DEFAULT 0,
    CONSTRAINT "pk_lease" PRIMARY KEY (
        "lease_number"
     )
);

CREATE TABLE "invoice" (
    "invoice_number" NUMBER GENERATED by default on null as IDENTITY,
    "semester" DATE   NOT NULL,
    "payment_due" DATE   NOT NULL,
    "paid_in_full" DATE   NOT NULL,
    "reminder_1" DATE   NOT NULL,
    "reminder_2" DATE   NOT NULL,
    "method_of_payment" NUMBER   NOT NULL,
    "billee" NUMBER   NOT NULL,
    "lease_number" NUMBER   NOT NULL,
    "amount" DECIMAL(6,2)  DEFAULT 0.0 NOT NULL,
    CONSTRAINT "pk_invoice" PRIMARY KEY (
        "invoice_number"
     )
);

CREATE TABLE "payment_types" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "method_name" VARCHAR2(70)   NOT NULL,
    "description" VARCHAR2(70),
    CONSTRAINT "pk_payment_types" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "course" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "number" NUMBER   NOT NULL,
    "title" VARCHAR2(70) NOT NULL,
    "instructor" NUMBER   NOT NULL,
    "instructor_campus_phone" VARCHAR2(70),
    CONSTRAINT "pk_course" PRIMARY KEY (
        "id"
     )
);

CREATE TABLE "address" (
    "id" NUMBER GENERATED by default on null as IDENTITY,
    "street_number" VARCHAR2(70)   NOT NULL,
    "street_name" VARCHAR2(70) NOT NULL,
    "city" VARCHAR2(70)   NOT NULL,
    "state" VARCHAR2(70)   NOT NULL,
    "zip_code" VARCHAR2(70)   NOT NULL,
    CONSTRAINT "pk_address" PRIMARY KEY (
        "id"
     )
);

